// Whole-body LQR gain table for V3Controller::Algo::WholeBody.
//
//   wb_lqr_design                     summary per height
//   wb_lqr_design --out <header>      also write the gain table header
//
// The model, cost and solver are in src_fw/tests/WbDesign.hpp; the table is
// src_fw/include/tap_fw/v3/WholeBodyGains.hpp (generated, do not edit).
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "WbDesign.hpp"

using tap_fw::sim::WbActuators;
using tap_fw::sim::WbDesign;
using tap_fw::sim::WbPoint;
using tap_fw::sim::WbWeights;
using tap_fw::v3::LegHeight;

namespace {

constexpr int kHeights = 12;

std::vector<WbPoint> designAll(const WbDesign& d) {
  std::vector<WbPoint> pts;
  const double lo = LegHeight::minHeight(), hi = LegHeight::maxHeight();
  for (int i = 0; i < kHeights; ++i) {
    pts.push_back(d.design(lo + (hi - lo) * i / (kHeights - 1)));
  }
  return pts;
}

void writeTable(FILE* f, const char* name, const std::vector<WbPoint>& pts) {
  std::fprintf(f, "inline constexpr std::array<Point, kHeights> %s{{\n", name);
  for (const auto& p : pts) {
    std::fprintf(f, "    {%.6fF, %.6fF, %.6fF, %.6fF,\n     {{", p.height_m, p.theta0, p.q0, p.k0);
    for (int r = 0; r < 3; ++r) {
      std::fprintf(f, "%s{", r ? ",\n       " : "");
      for (int c = 0; c < p.K.cols(); ++c) {
        std::fprintf(f, "%s%.7gF", c ? ", " : "", p.K(r, c));
      }
      std::fprintf(f, "}");
    }
    std::fprintf(f, "}}},\n");
  }
  std::fprintf(f, "}};\n\n");
}

void writeHeader(const char* path, const WbDesign& d, const std::vector<WbPoint>& pts,
                 const std::vector<WbPoint>& soft) {
  FILE* f = std::fopen(path, "w");
  if (!f) {
    std::perror(path);
    return;
  }
  const auto& a = d.actuators();
  std::fprintf(f,
               "#pragma once\n"
               "// Generated by src_fw/tools/wb_lqr_design.cpp; do not edit.\n"
               "// Whole-body LQR (V3Controller::Algo::WholeBody): wheel speed, hip and\n"
               "// knee offset commands from the state X (WbDesign.hpp layout):\n"
               "//   [x - x_ref, th - th0, q - q0, k - k0, x' - x'_ref, th', q', k',\n"
               "//    integral of x - x_ref, past wheel commands (newest first, kWheelDelay),\n"
               "//    past hip offsets - q0 (kJointDelay), past knee offsets - k0 (kJointDelay)]\n"
               "// u = u0 - K X, u0 = (x'_ref / R, q0, k0). Design: dt %.4f s, wheel lag %.3f s,\n"
               "// dead time %d ticks, joint delay %d ticks, hip kp %.1f kv %.3f, knee kp %.1f\n"
               "// kv %.3f, body CoM dx %.4f m.\n"
               "#include <array>\n\n"
               "namespace tap_fw::v3::wb {\n\n"
               "inline constexpr int kHeights = %d;\n"
               "inline constexpr int kWheelDelay = %d;\n"
               "inline constexpr int kJointDelay = %d;\n"
               "inline constexpr int kStates = %d;\n"
               "inline constexpr float kDt = %.6fF;\n\n"
               "struct Point {\n"
               "  float height_m, theta0, q0, k0;\n"
               "  std::array<std::array<float, kStates>, 3> K;\n"
               "};\n\n"
               "// kTable: the stiff body hold; kTableSoft: the looser set the\n"
               "// controller blends toward near the wheel cap (WbDesign softWeights).\n",
               a.dt, a.wheel_tau, a.wheel_delay_ticks, a.joint_delay_ticks, a.hip_kp, a.hip_kv,
               a.knee_kp, a.knee_kv, a.body_dx, kHeights, a.wheel_delay_ticks,
               a.joint_delay_ticks, d.n(), a.dt);
  writeTable(f, "kTable", pts);
  writeTable(f, "kTableSoft", soft);
  std::fprintf(f, "}  // namespace tap_fw::v3::wb\n");
  std::fclose(f);
  std::printf("wrote %s\n", path);
}

}  // namespace

int main(int argc, char** argv) {
  const char* out = nullptr;
  for (int i = 1; i < argc; ++i) {
    if (!std::strcmp(argv[i], "--out") && i + 1 < argc) out = argv[++i];
  }
  const WbDesign d(WbActuators{}, WbWeights{});
  const auto pts = designAll(d);
  const WbDesign ds(WbActuators{}, tap_fw::sim::softWeights());
  const auto soft = designAll(ds);
  std::printf("states %d (8 + integral + %d wheel + 2 x %d joint delay)\n", d.n(),
              d.actuators().wheel_delay_ticks, d.actuators().joint_delay_ticks);
  for (const auto& p : pts) {
    std::printf("h %5.1f mm: th0 %+.4f q0 %+.3f k0 %+.3f  |eig| %.6f  K wheel[x th q k] "
                "%+.1f %+.1f %+.1f %+.1f  hip %+.3f %+.3f %+.3f %+.3f  knee %+.3f %+.3f %+.3f %+.3f\n",
                p.height_m * 1000, p.theta0, p.q0, p.k0, p.max_closed_loop_eig, p.K(0, 0),
                p.K(0, 1), p.K(0, 2), p.K(0, 3), p.K(1, 0), p.K(1, 1), p.K(1, 2), p.K(1, 3),
                p.K(2, 0), p.K(2, 1), p.K(2, 2), p.K(2, 3));
  }
  if (out) writeHeader(out, d, pts, soft);
  return 0;
}
